const raw = $input.first().json;
const payload = raw.body || raw;
const isEmptyPayload = !payload || Object.keys(payload).length === 0;

// Manual test runs have no payload - default to a sample incident so the workflow is testable end to end
const triggerIncidentId = payload.incidentId || payload.id || (isEmptyPayload ? 'INC-TEST-001' : null);
const triggerService = payload.service || payload.affectedService || (isEmptyPayload ? 'checkout-api' : null);
const triggerSeverity = payload.severity || (isEmptyPayload ? 'P3' : null);
const triggerSource = payload.source || payload.alertSource || (isEmptyPayload ? 'manual-test' : 'unknown');
const triggerDescription = payload.description || payload.summary || (isEmptyPayload ? 'Elevated 5xx error rate on checkout-api' : '');

return [{
  json: {
    triggerIncidentId: triggerIncidentId || null,
    triggerService: triggerService || null,
    triggerSeverity: triggerSeverity || null,
    triggerSource,
    triggerDescription,
    results: [],
    processedCount: 0
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    queue: [{
      incidentId: item.triggerIncidentId,
      service: item.triggerService || '',
      severity: item.triggerSeverity || 'P3',
      source: item.triggerSource,
      description: item.triggerDescription
    }]
  }
}];

const state = $('If Ad Hoc Incident Provided').first().json;
const response = $input.first().json;
const incidents = response.incidents || response.items || (Array.isArray(response) ? response : []);

const queue = incidents.map(i => ({
  incidentId: i.incidentId || i.id || String(i),
  service: i.service || i.affectedService || '',
  severity: i.severity || 'P3',
  source: i.source || i.alertSource || 'incident-manager',
  description: i.description || i.summary || ''
}));

return [{
  json: {
    ...state,
    queue
  }
}];

const item = $input.first().json;
const queue = [...(item.queue || [])];
const next = queue.shift();

return [{
  json: {
    ...item,
    queue,
    currentIncidentId: next ? next.incidentId : null,
    currentService: next ? next.service : null,
    currentSeverity: next ? next.severity : null,
    currentSource: next ? next.source : null,
    currentDescription: next ? next.description : null,
    hasNext: !!next
  }
}];

const state = $('Get Next Incident from Queue').first().json;
const deploysResponse = $input.first().json;
const metricsResponse = $('Fetch Incident Diagnostics').first().json;

const metrics = metricsResponse.metrics || metricsResponse.series || metricsResponse || {};
const deploys = deploysResponse.deployments || deploysResponse.items || (Array.isArray(deploysResponse) ? deploysResponse : []);

const recentDeploys = deploys.slice(0, 5).map(d => ({
  service: d.service || state.currentService,
  version: d.version || d.sha || '',
  deployedAt: d.deployedAt || d.timestamp || '',
  deployedBy: d.deployedBy || d.author || ''
}));

return [{
  json: {
    ...state,
    diagnosticsFetchedAt: new Date().toISOString(),
    metricsSnapshot: metrics,
    recentDeploys
  }
}];

const aiResponse = $input.first().json;
const state = $('Normalize Diagnostics').first().json;

let triage;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  triage = JSON.parse(cleaned);
} catch (e) {
  triage = { severity: state.currentSeverity, confidence: 0, likelyRootCause: '', affectedComponents: [], suspectDeploy: null, summary: 'Unable to parse AI response' };
}

return [{
  json: {
    ...state,
    triage
  }
}];

const aiResponse = $input.first().json;
const state = $('Parse Triage Analysis').first().json;

let plan;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  plan = JSON.parse(cleaned);
} catch (e) {
  plan = { action: 'no_action_monitor', actionParams: {}, riskLevel: 'high', riskReason: 'Unable to parse AI response', rollbackPlan: '', reasoning: 'Falling back to monitor-only due to parse failure' };
}

const severityRank = { P1: 1, P2: 2, P3: 3, P4: 4 };
const currentRank = severityRank[state.currentSeverity] || 4;
const thresholdRank = severityRank[state.autoRemediateMaxSeverity] || 3;

// Require human approval for medium/high risk actions, or for severities more urgent than the configured auto-remediate threshold
const requiresApproval = plan.riskLevel === 'high' || plan.riskLevel === 'medium' || currentRank < thresholdRank;

return [{
  json: {
    ...state,
    remediationPlan: plan,
    requiresApproval
  }
}];

const state = $('Parse Remediation Plan').first().json;

return [{
  json: {
    ...state,
    remediationExecuted: false,
    remediationStatus: 'pending_approval'
  }
}];

const state = $('Parse Remediation Plan').first().json;
const execResponse = $input.first().json;

return [{
  json: {
    ...state,
    remediationExecuted: true,
    remediationStatus: execResponse.status || execResponse.result || 'executed',
    remediationExecutionResponse: execResponse
  }
}];

// Merge point: both the "pending approval" and "executed" branches land here
// with the same shape, so downstream nodes can safely reference this node by name.
return [{ json: $input.first().json }];

const aiResponse = $input.first().json;
const state = $('Prepare Communications Prompt').first().json;

let comms;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  comms = JSON.parse(cleaned);
} catch (e) {
  comms = { statusUpdate: 'Status update unavailable - AI response could not be parsed.', internalNote: '', nextCheckInMinutes: 30 };
}

return [{
  json: {
    ...state,
    communicationsDraft: comms
  }
}];

const state = $('Parse Communications Draft').first().json;

const incidentReport = {
  incidentId: state.currentIncidentId,
  service: state.currentService,
  reportedSeverity: state.currentSeverity,
  triage: state.triage,
  remediationPlan: state.remediationPlan,
  remediationStatus: state.remediationStatus,
  communications: state.communicationsDraft,
  loggedAt: new Date().toISOString()
};

return [{
  json: {
    ...state,
    results: [...(state.results || []), incidentReport],
    processedCount: (state.processedCount || 0) + 1
  }
}];

const item = $input.first().json;
const results = item.results || [];

const bySeverity = {};
for (const r of results) {
  const sev = r.reportedSeverity || 'unknown';
  bySeverity[sev] = (bySeverity[sev] || 0) + 1;
}

const autoRemediatedCount = results.filter(r => r.remediationStatus && r.remediationStatus !== 'pending_approval').length;
const pendingApprovalCount = results.filter(r => r.remediationStatus === 'pending_approval').length;

return [{
  json: {
    slackAlertsWebhookUrl: item.slackAlertsWebhookUrl,
    incidentsProcessed: results.length,
    bySeverity,
    autoRemediatedCount,
    pendingApprovalCount,
    incidentReports: results
  }
}];

const raw = $input.first().json;
const payload = raw.body || raw;

return [{
  json: {
    incidentId: payload.incidentId,
    service: payload.service,
    action: payload.action,
    actionParams: payload.actionParams || {},
    approved: !!payload.approved,
    approvedBy: payload.approvedBy || 'unknown',
    // Duplicated here since this is a separate trigger with no access to the main run's config node
    runbookExecuteUrl: 'https://api.yourrunbookengine.com/v1/execute',
    slackAlertsWebhookUrl: 'https://hooks.slack.com/services/your/alerts/webhook'
  }
}];

const state = $('Parse Approval Callback').first().json;
return [{
  json: {
    status: 'declined',
    incidentId: state.incidentId,
    message: 'Remediation was declined and was not executed.'
  }
}];
